import { useForm, FormProvider } from 'react-hook-form';
import { 금액확인Context } from '~/widgets/exchange-convert-to-deposit-funnel/model/schemas';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { PhaseType } from '~/entities/exchange/model/constants';
import { ConfirmInfo } from '~/entities/exchange-input-confirm/ui/confirm-info';
import { findTokenItemById, getTokenItemLabel } from '~/entities/user';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { getExchangeTransactionLabel } from '~/entities/wallet/lib/get-trnsc-type-label';
import i18n from '~/shared/i18n/i18n';
import { usePinBottomSheet } from '~/shared/lib/hooks/use-pin-bottom-sheet';

type Props = {
  context: 금액확인Context;
  onNext: (params: 금액확인Context) => void;
  onError: (error: Error) => void;
};

export const InputConfirmPage = ({ context, onNext, onError }: Props) => {
  const { openPinBottomSheet } = usePinBottomSheet();

  const { data: userRes } = useGetUserInfoQuery();

  const tokenItem = findTokenItemById(userRes?.tbCstmrMastr?.tokenList, context.tokenId);
  const tokenLabel = getTokenItemLabel(tokenItem);
  const { shortBankName: tokenBankLabel } = useComBankInfo(tokenItem?.bankCd ?? '');

  const form = useForm();

  const handleSubmit = form.handleSubmit(async () => {
    if (context.txCd) {
      openPinBottomSheet((close) => {
        close();
        setTimeout(() => {
          onNext({
            ...context,
          });
        }, 0);
      });
    }
  });

  const transactionLabel = getExchangeTransactionLabel(context.trnscTypeCd);

  return (
    <FormProvider {...form}>
      <div className="wrap bgw">
        <div className="content sub has-btm-btn">
          <ConfirmInfo amount={Number(context.trnscAmt)} phase={PhaseType.Confirm} transactionLabel={transactionLabel}>
            <div className="whitespace-pre-wrap">
              {i18n.t('text:fromAAndBToLinkedAccountCAndD', {
                a: tokenLabel || '',
                b: userRes?.tbCstmrMastr?.bankNm || '',
                c: tokenBankLabel || '',
                d: userRes?.tbCstmrMastr?.realAcnutNo || '',
              })}
            </div>
          </ConfirmInfo>
        </div>
        <div className="btm-btn-area" id="confirm-btn-area">
          <button type="button" className="btm-btn app" id="confirm-btn" onClick={handleSubmit}>
            {transactionLabel}하기
          </button>
        </div>
      </div>
    </FormProvider>
  );
};
